// tiered-access.ts
export class TieredAccessSystem {
  private userTier: string;
  private featureLimits: Record<string, number>;
  private apiQuota: number;

  constructor(userTier: string) {
    this.userTier = userTier;
    this.featureLimits = this.initializeFeatureLimits(userTier);
    this.apiQuota = this.initializeApiQuota(userTier);
  }

  private initializeFeatureLimits(tier: string): Record<string, number> {
    const limits = {
      basic: { codeCompletion: 1, advancedRag: 0, fusion: 0 },
      enhanced: { codeCompletion: 10, advancedRag: 5, fusion: 0 },
      premium: { codeCompletion: 50, advancedRag: 20, fusion: 10 },
      developer: { codeCompletion: 100, advancedRag: 50, fusion: 30 }
    };
    return limits[tier] || limits.basic;
  }

  private initializeApiQuota(tier: string): number {
    const quotas = {
      basic: 20,
      enhanced: 60,
      premium: 120,
      developer: 300
    };
    return quotas[tier] || quotas.basic;
  }

  checkFeatureAccess(feature: string): boolean {
    return this.featureLimits[feature] > 0;
  }

  consumeQuota(amount: number = 1): boolean {
    if (this.apiQuota >= amount) {
      this.apiQuota -= amount;
      return true;
    }
    return false;
  }

  getRemainingQuota(): number {
    return this.apiQuota;
  }
}
